package webhooks_test

import (
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"strings"
	"testing"
	"time"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/store"
	"example.com/tally/internal/webhooks"
)

func TestSign(t *testing.T) {
	// HMAC-SHA256("key", "The quick brown fox jumps over the lazy dog")
	const want = "f7bc83f430538424b13298e6aa6fb143ef4d59a14946175997479dbc2d1a3cd8"
	if got := webhooks.Sign("key", []byte("The quick brown fox jumps over the lazy dog")); got != want {
		t.Fatalf("Sign = %s", got)
	}
}

// sigOf is the reference computation of a v1 signature: HMAC-SHA256 of "<t>.<body>".
func sigOf(secret string, unix int64, body []byte) string {
	m := hmac.New(sha256.New, []byte(secret))
	m.Write([]byte(fmt.Sprintf("%d.", unix)))
	m.Write(body)
	return hex.EncodeToString(m.Sum(nil))
}

func TestSignatureHeader(t *testing.T) {
	body := []byte(`{"id":"evt_1"}`)
	at := time.Unix(1700000000, 0)
	got := webhooks.SignatureHeader([]string{"whsec_new", "whsec_old"}, at, body)
	want := "t=1700000000,v1=" + sigOf("whsec_new", 1700000000, body) + ",v1=" + sigOf("whsec_old", 1700000000, body)
	if got != want {
		t.Fatalf("SignatureHeader =\n%s\nwant\n%s", got, want)
	}
	if got := webhooks.SignatureHeader([]string{"whsec_only"}, at, body); got != "t=1700000000,v1="+sigOf("whsec_only", 1700000000, body) {
		t.Fatalf("one secret: %s", got)
	}
	// Sub-second parts of the time are not sent.
	if got := webhooks.SignatureHeader([]string{"whsec_only"}, at.Add(900*time.Millisecond), body); !strings.HasPrefix(got, "t=1700000000,") {
		t.Fatalf("sub-second: %s", got)
	}
}

func TestVerify(t *testing.T) {
	body := []byte(`{"id":"evt_1","type":"invoice.paid"}`)
	base := time.Unix(1700000000, 0)
	sig := sigOf("whsec_a", 1700000000, body)
	header := "t=1700000000,v1=" + sig

	ok := []struct {
		name      string
		header    string
		now       time.Time
		tolerance time.Duration
	}{
		{"exact time", header, base, 0},
		{"five minutes late, default tolerance", header, base.Add(5 * time.Minute), 0},
		{"five minutes early, default tolerance", header, base.Add(-5 * time.Minute), 0},
		{"within a given tolerance", header, base.Add(59 * time.Second), time.Minute},
		{"spaces around pairs", " t = 1700000000 ,  v1 = " + sig + " ", base, 0},
		{"any order", "v1=" + sig + ",t=1700000000", base, 0},
		{"unknown keys are ignored", "t=1700000000,v0=beef,v1=" + sig, base, 0},
		{"a later v1 matches", "t=1700000000,v1=00,v1=" + sig, base, 0},
	}
	for _, c := range ok {
		if err := webhooks.Verify(body, c.header, []string{"whsec_a"}, c.tolerance, c.now); err != nil {
			t.Errorf("%s: %v", c.name, err)
		}
	}

	// The secret that matches may be any of several.
	if err := webhooks.Verify(body, header, []string{"whsec_x", "", "whsec_a"}, 0, base); err != nil {
		t.Errorf("second secret: %v", err)
	}

	bad := []struct {
		name      string
		payload   []byte
		header    string
		secrets   []string
		now       time.Time
		tolerance time.Duration
		want      error
	}{
		{"empty header", body, "", []string{"whsec_a"}, base, 0, webhooks.ErrMalformedHeader},
		{"blank header", body, "  ", []string{"whsec_a"}, base, 0, webhooks.ErrMalformedHeader},
		{"pair without =", body, "t=1700000000,v1", []string{"whsec_a"}, base, 0, webhooks.ErrMalformedHeader},
		{"empty pair", body, "t=1700000000,,v1=" + sig, []string{"whsec_a"}, base, 0, webhooks.ErrMalformedHeader},
		{"t is not an integer", body, "t=yesterday,v1=" + sig, []string{"whsec_a"}, base, 0, webhooks.ErrMalformedHeader},
		{"t is a decimal", body, "t=1700000000.5,v1=" + sig, []string{"whsec_a"}, base, 0, webhooks.ErrMalformedHeader},
		{"pairs without a comma", body, "t=1700000000 v1=" + sig, []string{"whsec_a"}, base, 0, webhooks.ErrMalformedHeader},
		{"no t", body, "v1=" + sig, []string{"whsec_a"}, base, 0, webhooks.ErrNoTimestamp},
		{"no t, no v1", body, "v0=beef", []string{"whsec_a"}, base, 0, webhooks.ErrNoTimestamp},
		{"too old", body, header, []string{"whsec_a"}, base.Add(5*time.Minute + time.Second), 0, webhooks.ErrTimestampTolerance},
		{"too new", body, header, []string{"whsec_a"}, base.Add(-5*time.Minute - time.Second), 0, webhooks.ErrTimestampTolerance},
		{"outside a given tolerance", body, header, []string{"whsec_a"}, base.Add(time.Minute + time.Second), time.Minute, webhooks.ErrTimestampTolerance},
		{"timestamp checked before signatures", body, "t=1", []string{"whsec_a"}, base, 0, webhooks.ErrTimestampTolerance},
		{"no v1", body, "t=1700000000", []string{"whsec_a"}, base, 0, webhooks.ErrNoSignature},
		{"no v1 and the tolerance is checked first", body, "t=1", []string{"whsec_a"}, base, 0, webhooks.ErrTimestampTolerance},
		{"v1 that is not the signature", body, "t=1700000000,v1=beef", []string{"whsec_a"}, base, 0, webhooks.ErrSignatureMismatch},
		{"wrong secret", body, header, []string{"whsec_b"}, base, 0, webhooks.ErrSignatureMismatch},
		{"no secrets", body, header, nil, base, 0, webhooks.ErrSignatureMismatch},
		{"only an empty secret", body, "t=1700000000,v1=" + sigOf("", 1700000000, body), []string{""}, base, 0, webhooks.ErrSignatureMismatch},
		{"tampered body", []byte(`{"id":"evt_2"}`), header, []string{"whsec_a"}, base, 0, webhooks.ErrSignatureMismatch},
		{"timestamp changed", body, "t=1700000001,v1=" + sig, []string{"whsec_a"}, base.Add(time.Second), 0, webhooks.ErrSignatureMismatch},
		{"signature of the body without a timestamp", body, "t=1700000000,v1=" + hexOfSum(body), []string{"whsec_a"}, base, 0, webhooks.ErrSignatureMismatch},
	}
	for _, c := range bad {
		err := webhooks.Verify(c.payload, c.header, c.secrets, c.tolerance, c.now)
		if !errors.Is(err, c.want) {
			t.Errorf("%s: Verify = %v, want %v", c.name, err, c.want)
		}
	}
}

// hexOfSum is the HMAC-SHA256 of body keyed with the empty string, a signature no endpoint has.
func hexOfSum(body []byte) string { return webhooks.Sign("", body) }

func TestCheckURL(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	for _, ok := range []string{"https://hooks.acme.example/tally", "https://93.184.216.34:8443/in"} {
		if err := e.Webhooks.CheckURL(ctx, ok); err != nil {
			t.Errorf("CheckURL(%q) = %v", ok, err)
		}
	}
	for _, bad := range []string{"", "hooks.acme.example/x", "ftp://hooks.acme.example/", "https:///x", "https://unknown.example/x"} {
		if err := e.Webhooks.CheckURL(ctx, bad); !errors.Is(err, webhooks.ErrInvalidURL) {
			t.Errorf("CheckURL(%q) = %v, want ErrInvalidURL", bad, err)
		}
	}
	if err := webhooks.CheckEvents([]string{"invoice.paid", "*"}); err != nil {
		t.Error(err)
	}
	for _, bad := range [][]string{nil, {"invoice.eaten"}} {
		if err := webhooks.CheckEvents(bad); !errors.Is(err, webhooks.ErrInvalidEvents) {
			t.Errorf("CheckEvents(%v) = %v", bad, err)
		}
	}
}

func TestPublishAndDeliver(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	now := e.Clock.Now()
	all, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/all", Events: []string{"*"}, Secret: "whsec_a", Enabled: true}, now)
	paid, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/paid", Events: []string{"invoice.paid"}, Secret: "whsec_b", Enabled: true}, now)
	_, _ = e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/off", Events: []string{"*"}, Secret: "whsec_c", Enabled: false}, now)
	_, _ = e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Globex.ID, URL: "https://hooks.globex.example/", Events: []string{"*"}, Secret: "whsec_d", Enabled: true}, now)

	if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_1"}); err != nil {
		t.Fatal(err)
	}
	n, err := e.Webhooks.RunDue(ctx)
	if err != nil || n != 1 {
		t.Fatalf("RunDue = %d, %v (only the endpoint for every event wants customer.created)", n, err)
	}
	reqs := e.HTTP.Requests()
	if len(reqs) != 1 || reqs[0].URL != all.URL || reqs[0].Method != http.MethodPost {
		t.Fatalf("requests = %+v", reqs)
	}
	if got, want := reqs[0].Header.Get("Tally-Signature"), webhooks.SignatureHeader([]string{"whsec_a"}, now, reqs[0].Body); got != want {
		t.Fatalf("signature %q, want %q", got, want)
	}
	if err := webhooks.Verify(reqs[0].Body, reqs[0].Header.Get("Tally-Signature"), []string{"whsec_a"}, 0, e.Clock.Now()); err != nil {
		t.Fatalf("the receiver cannot verify the delivery: %v", err)
	}
	var body webhooks.Body
	if err := json.Unmarshal(reqs[0].Body, &body); err != nil || body.Type != "customer.created" || reqs[0].Header.Get("Tally-Event-Id") != body.ID {
		t.Fatalf("body = %s (%v)", reqs[0].Body, err)
	}
	ds := e.Store.Deliveries(e.Acme.ID, all.ID)
	if len(ds) != 1 || ds[0].Status != store.DeliverySucceeded || ds[0].Attempts != 1 || ds[0].ResponseStatus != 200 {
		t.Fatalf("deliveries = %+v", ds)
	}

	e.HTTP.Respond = func(r apitest.Request) (int, error) { return http.StatusInternalServerError, nil }
	_ = e.Webhooks.Publish(ctx, e.Acme.ID, "invoice.paid", map[string]string{"invoice_id": "in_1"})
	if n, _ := e.Webhooks.RunDue(ctx); n != 2 {
		t.Fatalf("RunDue = %d, want 2", n)
	}
	for _, ep := range []store.WebhookEndpoint{all, paid} {
		ds := e.Store.Deliveries(e.Acme.ID, ep.ID)
		last := ds[len(ds)-1]
		if last.Status != store.DeliveryFailed || last.ResponseStatus != 500 || last.Error == "" {
			t.Fatalf("delivery to %s = %+v", ep.URL, last)
		}
	}
	if n, _ := e.Webhooks.RunDue(ctx); n != 0 {
		t.Fatalf("a failed delivery was sent again: %d", n)
	}
}

// rotationEnv is an Acme endpoint that subscribes to every event, with its original secret.
func rotationEnv(t *testing.T) (*apitest.Env, store.WebhookEndpoint) {
	t.Helper()
	e := apitest.New(t)
	var ep store.WebhookEndpoint
	e.MustDo(http.StatusCreated, "POST", "/v1/webhook-endpoints", e.Acme.Key, map[string]any{"url": "https://hooks.acme.example/tally", "events": []string{"*"}}, &ep)
	return e, ep
}

// deliverOne publishes an event, attempts its delivery and returns the body and Tally-Signature the endpoint received.
func deliverOne(t *testing.T, e *apitest.Env) ([]byte, string) {
	t.Helper()
	ctx := context.Background()
	if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_1"}); err != nil {
		t.Fatal(err)
	}
	if n, err := e.Webhooks.RunDue(ctx); err != nil || n != 1 {
		t.Fatalf("RunDue = %d, %v", n, err)
	}
	reqs := e.HTTP.Requests()
	last := reqs[len(reqs)-1]
	return last.Body, last.Header.Get("Tally-Signature")
}

func TestDeliveryTimestampIsTheAttemptTime(t *testing.T) {
	e, _ := rotationEnv(t)
	ctx := context.Background()
	if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_1"}); err != nil {
		t.Fatal(err)
	}
	e.Clock.Advance(7 * time.Minute) // the attempt is later than the event
	if _, err := e.Webhooks.RunDue(ctx); err != nil {
		t.Fatal(err)
	}
	reqs := e.HTTP.Requests()
	want := fmt.Sprintf("t=%d,", e.Clock.Now().Unix())
	if got := reqs[0].Header.Get("Tally-Signature"); !strings.HasPrefix(got, want) {
		t.Fatalf("signature %q, want it to start with %q", got, want)
	}
}

func TestSecretRotation(t *testing.T) {
	e, ep := rotationEnv(t)
	first := ep.Secret

	// Before any rotation: one v1 entry, which the receiver checks with the endpoint's secret.
	body, header := deliverOne(t, e)
	if strings.Count(header, ",v1=") != 1 {
		t.Fatalf("before rotation: %q", header)
	}
	if err := webhooks.Verify(body, header, []string{first}, 0, e.Clock.Now()); err != nil {
		t.Fatal(err)
	}

	// Rotate: the answer is the endpoint with a new secret, and it does not show the previous one.
	var rotated store.WebhookEndpoint
	r := e.MustDo(http.StatusOK, "POST", "/v1/webhook-endpoints/"+ep.ID+"/rotate-secret", e.Acme.Key, nil, &rotated)
	second := rotated.Secret
	if second == first || !strings.HasPrefix(second, "whsec_") || len(second) != len("whsec_")+32 {
		t.Fatalf("rotated secret = %q", second)
	}
	if _, err := hex.DecodeString(strings.TrimPrefix(second, "whsec_")); err != nil {
		t.Fatalf("rotated secret is not hex: %v", err)
	}
	if rotated.ID != ep.ID || rotated.URL != ep.URL || rotated.SecretRotatedAt == nil || rotated.PreviousSecret != "" {
		t.Fatalf("rotated endpoint = %+v", rotated)
	}
	if _, ok := r.Map(t)["previous_secret"]; ok {
		t.Fatalf("the API showed the previous secret: %s", r)
	}
	if got := e.Do("GET", "/v1/webhook-endpoints/"+ep.ID, e.Acme.Key, nil); strings.Contains(got.String(), first) {
		t.Fatalf("the API showed the previous secret: %s", got)
	}

	// For 24 hours both secrets sign, the new one first.
	rotatedAt := e.Clock.Now()
	e.Clock.Set(rotatedAt.Add(webhooks.SecretGracePeriod - time.Second))
	body, header = deliverOne(t, e)
	ts := e.Clock.Now().Unix()
	want := fmt.Sprintf("t=%d,v1=%s,v1=%s", ts, sigOf(second, ts, body), sigOf(first, ts, body))
	if header != want {
		t.Fatalf("during the grace period:\n%s\nwant\n%s", header, want)
	}
	if err := webhooks.Verify(body, header, []string{second}, 0, e.Clock.Now()); err != nil {
		t.Fatal(err)
	}
	if err := webhooks.Verify(body, header, []string{first}, 0, e.Clock.Now()); err != nil {
		t.Fatal(err)
	}

	// After 24 hours only the new secret signs.
	e.Clock.Set(rotatedAt.Add(webhooks.SecretGracePeriod))
	body, header = deliverOne(t, e)
	ts = e.Clock.Now().Unix()
	if want := fmt.Sprintf("t=%d,v1=%s", ts, sigOf(second, ts, body)); header != want {
		t.Fatalf("after the grace period: %s, want %s", header, want)
	}
	if err := webhooks.Verify(body, header, []string{first}, 0, e.Clock.Now()); !errors.Is(err, webhooks.ErrSignatureMismatch) {
		t.Fatalf("old secret after the grace period: %v", err)
	}
}

func TestRotateTwiceWithinGracePeriod(t *testing.T) {
	e, ep := rotationEnv(t)
	first := ep.Secret
	var r1, r2 store.WebhookEndpoint
	e.MustDo(http.StatusOK, "POST", "/v1/webhook-endpoints/"+ep.ID+"/rotate-secret", e.Acme.Key, nil, &r1)
	second := r1.Secret
	e.Clock.Advance(time.Hour)
	e.MustDo(http.StatusOK, "POST", "/v1/webhook-endpoints/"+ep.ID+"/rotate-secret", e.Acme.Key, nil, &r2)
	third := r2.Secret

	// The first secret is dropped at once: only the current and the one before it sign.
	body, header := deliverOne(t, e)
	ts := e.Clock.Now().Unix()
	if want := fmt.Sprintf("t=%d,v1=%s,v1=%s", ts, sigOf(third, ts, body), sigOf(second, ts, body)); header != want {
		t.Fatalf("header = %s, want %s", header, want)
	}
	if err := webhooks.Verify(body, header, []string{first}, 0, e.Clock.Now()); !errors.Is(err, webhooks.ErrSignatureMismatch) {
		t.Fatalf("the dropped secret still verifies: %v", err)
	}

	// The grace period of the second rotation runs from the second rotation.
	e.Clock.Advance(webhooks.SecretGracePeriod - time.Hour)
